package com.johnny.hotel.pricing;
import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;import static com.johnny.hotel.service.support.BillingRules.*;
@Service @RequiredArgsConstructor public class ManualRateService{private final PricingMapper db;private final PricingAccess access;private final RoomTypeMapper types;private final SysAuditLogMapper audits;
 public List<ManualRateOverride> range(Long type,LocalDate start,LocalDate end,Long actor){access.read(actor);dates(start,end.plusDays(1));return db.overrides(type,start,end);}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public List<ManualRateOverride> save(PricingRequests.Override r,Long actor){access.overrideWrite(actor);require(r.getEndDate()!=null&&!r.getEndDate().isBefore(r.getStartDate()),"Invalid override date range");require(Set.of("FIXED_RATE","PERCENT_OF_RECOMMENDED").contains(r.getOverrideType()),"Invalid override type");require(r.getReason()!=null&&!r.getReason().isBlank(),"Override reason is required");require(types.selectByIdForUpdate(r.getRoomTypeId())!=null,"Room type does not exist");if("FIXED_RATE".equals(r.getOverrideType()))require(money(r.getValue(),10).signum()>0,"Fixed rate must be positive");db.lockControl();var out=new ArrayList<ManualRateOverride>();for(LocalDate d=r.getStartDate();!d.isAfter(r.getEndDate());d=d.plusDays(1)){var old=db.override(r.getRoomTypeId(),d);var x=ManualRateOverride.builder().id(old==null?null:old.getId()).roomTypeId(r.getRoomTypeId()).stayDate(d).overrideType(r.getOverrideType()).overrideValue(r.getValue()).reason(r.getReason().trim()).createdBy(old==null?actor:old.getCreatedBy()).updatedBy(actor).build();one(old==null?db.insertOverride(x):db.updateOverride(x));out.add(db.override(r.getRoomTypeId(),d));audit(actor,"MANUAL_RATE_OVERRIDE",r.getRoomTypeId()+"/"+d+" old="+(old==null?"NONE":old.getOverrideType()+":"+old.getOverrideValue())+" new="+r.getOverrideType()+":"+r.getValue()+" reason="+r.getReason().trim());}return out;}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public void cancel(Long type,LocalDate date,String reason,Long actor){access.overrideWrite(actor);require(reason!=null&&!reason.isBlank(),"Cancellation reason is required");db.lockControl();var x=db.override(type,date);require(x!=null,"Manual override does not exist");one(db.cancelOverride(x.getId(),actor,reason.trim()));audit(actor,"MANUAL_RATE_OVERRIDE_CANCEL",type+"/"+date+" old="+x.getOverrideType()+":"+x.getOverrideValue()+" reason="+reason.trim());}
 private void audit(Long actor,String action,String detail){one(audits.insert(SysAuditLog.builder().operatorId(actor).action(action).detail(detail).build()));}
}
